import sqlite3
import json
import os

db = os.path.join(os.environ["USERPROFILE"], ".cc-switch", "cc-switch.db")
c = sqlite3.connect(db)
rows = c.execute(
    "SELECT id, name, app_type, settings_config FROM providers "
    "WHERE app_type='codex' OR id LIKE '%codex%' OR name LIKE '%codex%' "
    "OR name LIKE '%official%' OR name LIKE '%hctopup%' OR name LIKE '%one-api%'"
).fetchall()
for pid, name, app_type, cfg in rows:
    print("===", pid, "|", name, "|", app_type, "===")
    data = json.loads(cfg)
    if "config" in data:
        for line in str(data["config"]).splitlines():
            if any(k in line for k in ("model_provider", "base_url", "requires_openai", "wire_api", "name =")):
                print(line.strip())
    if "auth" in data:
        auth = data["auth"]
        print("auth keys:", list(auth.keys()) if isinstance(auth, dict) else type(auth))
        if isinstance(auth, dict):
            print("auth_mode:", auth.get("auth_mode"))
            print("OPENAI_API_KEY:", ("set" if auth.get("OPENAI_API_KEY") else "null"))
    if "env" in data:
        print("env:", {k: ("***" if "KEY" in k or "TOKEN" in k else v) for k, v in data.get("env", {}).items()})
    print()

